import boto3
import os

AWS_REGION = os.environ.get("AWS_REGION", "us-east-1")

def summarize_audit_events(event_text: str) -> dict:
    comprehend = boto3.client("comprehend", region_name=AWS_REGION)
    try:
        # Detect the dominant language to help Comprehend with better analysis
        language_detection_response = comprehend.detect_dominant_language(Text=event_text)
        dominant_language = language_detection_response["Languages"][0]["LanguageCode"]

        # Use detect_key_phrases to extract key information as a form of summary
        key_phrases_response = comprehend.detect_key_phrases(
            Text=event_text,
            LanguageCode=dominant_language
        )
        key_phrases = [phrase["Text"] for phrase in key_phrases_response["KeyPhrases"]]

        return {"summary_phrases": key_phrases, "language": dominant_language}
    except Exception as e:
        return {"error": str(e)}

import os
import requests
import json

AZURE_CONTENT_MODERATOR_ENDPOINT = os.environ.get("AZURE_CONTENT_MODERATOR_ENDPOINT")
AZURE_CONTENT_MODERATOR_KEY = os.environ.get("AZURE_CONTENT_MODERATOR_KEY")

def moderate_text_claim(text_claim: str) -> dict:
    if not AZURE_CONTENT_MODERATOR_ENDPOINT or not AZURE_CONTENT_MODERATOR_KEY:
        raise ValueError("Azure Content Moderator endpoint and key must be set in environment variables.")

    text_moderation_url = f"{AZURE_CONTENT_MODERATOR_ENDPOINT}/contentmoderator/moderate/v2.0/ProcessText/Screen?classify=True"

    headers = {
        'Ocp-Apim-Subscription-Key': AZURE_CONTENT_MODERATOR_KEY,
        'Content-Type': 'text/plain',
    }

    try:
        response = requests.post(text_moderation_url, headers=headers, data=text_claim.encode('utf-8'))
        response.raise_for_status() 
        return response.json()
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}

from google.cloud import translate_v2 as translate
import os

# Google Cloud Translation automatically uses GOOGLE_APPLICATION_CREDENTIALS for authentication.
# Ensure this environment variable is set or configure ADC.

def translate_consent_copy(text: str, target_language: str, source_language: str = None) -> dict:
    translate_client = translate.Client()

    try:
        result = translate_client.translate(text, target_language=target_language, source_language=source_language)
        return {
            "translated_text": result["translatedText"],
            "source_language": result["detectedSourceLanguage"],
            "target_language": target_language,
        }
    except Exception as e:
        return {"error": str(e)}
